// Package verdicts persists the review queue's human verdicts to a JSON
// file on disk. Verdicts survived a restart before (in-memory only); now
// the accept/reject calls a human makes in the queue are a durable
// artifact, and the /verdicts report is generated from them.
package verdicts

import (
	"encoding/json"
	"os"
	"sort"
	"sync"
	"time"
)

// Entry is one recorded human verdict.
type Entry struct {
	DecisionID int64
	Verdict    string // "accepted" (human agrees with the agent) or "rejected" (human agrees with the shadow-LLM)
	RecordedAt time.Time
}

// Store guards a map of decisionID -> Entry with a mutex and can flush the
// current state to a JSON file after every write.
type Store struct {
	mu       sync.Mutex
	path     string
	verdicts map[int64]Entry
}

// NewStore returns a store writing to path. Pass an empty path to disable
// persistence (verdicts stay in memory only).
func NewStore(path string) *Store {
	return &Store{path: path, verdicts: make(map[int64]Entry)}
}

// Load reads previously-saved verdicts from disk, if any. Missing file is
// not an error — the queue starts blank.
func (s *Store) Load() error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.path == "" {
		return nil
	}
	f, err := os.Open(s.path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return err
	}
	defer f.Close()
	var saved map[string]Entry // JSON keys are strings; convert below.
	if err := json.NewDecoder(f).Decode(&saved); err != nil {
		return err
	}
	for k, e := range saved {
		var id int64
		if _, err := s.parseKey(k, &id); err != nil {
			continue
		}
		s.verdicts[id] = e
	}
	return nil
}

func (s *Store) parseKey(k string, id *int64) (ok bool, err error) {
	// strconv is small enough to inline here without importing it at the
	// top of the file's import block being used twice.
	*id, err = parseInt64(k)
	return err == nil, err
}

// parseInt64 is a tiny helper to avoid importing strconv just once.
func parseInt64(s string) (int64, error) {
	n := int64(0)
	neg := false
	for i, c := range s {
		if i == 0 && c == '-' {
			neg = true
			continue
		}
		if c < '0' || c > '9' {
			return 0, errInvalid
		}
		n = n*10 + int64(c-'0')
	}
	if neg {
		return -n, nil
	}
	return n, nil
}

var errInvalid = os.NewError("invalid integer")

// Record saves a verdict for the given decision ID and flushes to disk.
func (s *Store) Record(decisionID int64, verdict string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.verdicts[decisionID] = Entry{
		DecisionID: decisionID,
		Verdict:    verdict,
		RecordedAt: time.Now().UTC(),
	}
	return s.flushLocked()
}

func (s *Store) flushLocked() error {
	if s.path == "" {
		return nil
	}
	out := make(map[string]Entry, len(s.verdicts))
	for id, e := range s.verdicts {
		out[formatInt64(id)] = e
	}
	b, err := json.MarshalIndent(out, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(s.path, b, 0o644)
}

func formatInt64(n int64) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	digits := ""
	for n > 0 {
		digits = string(rune('0'+n%10)) + digits
		n /= 10
	}
	if neg {
		digits = "-" + digits
	}
	return digits
}

